use strict; use warnings;
my ($out, @roots) = @ARGV; my @l;
my @st = @roots;
while (@st) {
    my $p = pop @st;
    my @s = lstat $p or next;
    push @l, join(' ', $p, $s[1], $s[2], $s[7], $s[9]);
    if (-d _) { opendir(my $d, $p) or next; push @st, map { "$p/$_" } grep { !/^\.\.?$/ && $_ ne '.git' } readdir $d; next }
    if (-f _) { open(my $f, '<:raw', $p) or next; local $/; my $c = <$f>; push @l, "$p sum " . unpack('%32C*', $c) }
}
open(my $o, '>', $out) or die; print $o join("\n", sort @l), "\n";
